  "site.about.clubsEyebrow": "Мережа",
  "site.about.clubsText": "Кожен клуб має свій дім і свою спільноту, з єдиним технічним керівництвом.",
  "site.about.clubsTitle": "Наші клуби",
  "site.about.heroText": "Judo Arte e Vida народився в Алгарве навколо тренера та ідеї: дзюдо — це набагато більше, ніж спорт.",
  "site.about.heroTitle": "Родина навколо татамі",
  "site.about.story1": "Усе починається з Матіаша Лувави, дзюдоїста з 1994 року. Тренер з 2006 року й суддя з 2009-го, він став суддею елітного рівня і, зал за залом, побудував мережу клубів в Алгарве: Лагуш, Албуфейра, Алвор.",
  "site.about.story2": "Сьогодні Judo Arte e Vida об'єднує клуби, тренерів, спортсменів і родини, які поділяють ті самі цінності, а також платформу, що їх поєднує: реєстрація, внески, відвідування, змагання й рейтинг в одному місці.",
  "site.about.storyEyebrow": "Наша історія",
  "site.about.storyTitle": "Від першого татамі до мережі клубів",
