  "site.about.team.ariel.role": "Інструктор",
  "site.about.team.ariel.text": "Допомагає наймолодшим робити перші кроки.",
  "site.about.team.marco.name": "Marco",
  "site.about.team.marco.role": "Інструктор",
  "site.about.team.marco.text": "Дзюдоїст і тато в Judo Clube de Lagos.",
