  "site.about.team.matias.role": "Технічний керівник і тренер · 2-й дан",
  "site.about.team.matias.text": "Дзюдоїст з 1994 року, тренер з 2006-го, суддя елітного рівня.",
  "site.about.team.paul.name": "Paul",
  "site.about.team.paul.role": "Помічник тренера",
  "site.about.team.paul.text": "Поруч зі спортсменами на кожному тренуванні.",
  "site.about.teamEyebrow": "Команда",
  "site.about.teamTitle": "Хто зустріне тебе на татамі",
  "site.about.timeline.1994.text": "Матіаш Лувава починає займатися дзюдо.",
  "site.about.timeline.1994.title": "Перше татамі",
  "site.about.timeline.2006.text": "Він починає викладати: народжується ідея Judo Arte e Vida.",
