  "site.vision.heroText": "Ми хочемо, щоб кожна дитина, родина й спортсмен знаходили в дзюдо дисципліну, повагу й радість — у будь-якому клубі мережі.",
  "site.vision.heroTitle": "Дзюдо як школа життя, доступна кожному",
  "site.vision.mission1": "Дзюдо має моральний кодекс: повага, щирість, сміливість, самовладання. Ми несемо його з татамі додому, до школи й у життя.",
  "site.vision.mission2": "І ми хочемо, щоб клуби зосереджувалися на цьому, а не на паперах: тому мережа має платформу, яка сама веде внески, відвідування, змагання й рахунки.",
